sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float angle;
uniform float mirror;
half4 main(float2 coord) {
    float2 c = size * 0.5;
    float unit = 0.5 * min(size.x, size.y) * max(scale, 0.05);
    float a = radians(angle);
    float cs = cos(a);
    float sn = sin(a);
    float2 p = coord - c;
    p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y) / unit;
    float2 r = float2(1.0, 1.7320508);
    float2 h = r * 0.5;
    float2 ga = mod(p, r) - h;
    float2 gb = mod(p - h, r) - h;
    float2 g = dot(ga, ga) < dot(gb, gb) ? ga : gb;
    if (mirror > 0.5) {
        float2 id = p - g;
        float k = mod(floor(id.x + 0.5) + floor(id.y / 1.7320508 * 2.0 + 0.5), 2.0);
        g.x = mix(g.x, -g.x, k);
    }
    g *= unit;
    g = float2(cs * g.x - sn * g.y, sn * g.x + cs * g.y);
    return image.eval(clamp(c + g, float2(0.5), size - 0.5));
}
